"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["84693"],{29770(e){e.exports=JSON.parse('{"id":"FIN-106","slug":"t-account","term":"T-Account","also_known_as":[],"difficulty":"Beginner","definition":"A T-account is a simple visual way of showing a single account, drawn in the shape of a letter T, with debits recorded on the left and credits on the right.","explanation":["The account name goes at the top of the T. Increases and decreases are written on the two sides according to the rules of debits and credits, and the balance is found by comparing the two sides.","Consider a cash T-account. A starting balance of 5,000 and receipts of 3,000 go on the left, the debit side. Payments of 2,500 go on the right, the credit side. The debit side totals 8,000 and the credit side 2,500, so the account has a debit balance of 5,500.","T-accounts are mainly a learning and thinking tool. Students use them to see clearly how a transaction affects each account, and accountants sketch them to work out complicated entries or to trace errors.","In practice, businesses record transactions in software, which shows account balances in tables rather than T-shapes. The logic, however, is exactly the same: every transaction appears as a debit in at least one account and a credit in at least one other."],"note":"","total":1500,"prev":{"slug":"systemically-important-bank","term":"Systemically Important Bank"},"next":{"slug":"tactical-asset-allocation","term":"Tactical Asset Allocation"}}')}}]);